import React, { memo } from 'react';
import { motion } from 'framer-motion';
import Animated from './Animated';
import ResponsiveImage from './ResponsiveImage';
import { glassPanelClass, commonShadow } from '../utils/uiEffects';

;

const ProductCard = ({ product, onClick, index, variant = 'card' }) => {
  return variant === 'list' ? (
    <Animated
      key={product.id}
      className={`group relative w-full overflow-hidden cursor-pointer py-4 md:py-5`}
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.32, delay: index * 0.04 }}
      onClick={() => onClick(product.id)}
      whileHover={{ translateY: -2 }}
      promoteOnHover
    >
      <div className={`max-w-4xl mx-auto w-full px-4 md:px-6 md:flex md:items-center md:gap-6 md:flex-row-reverse ${glassPanelClass} border border-obsidian/10 ${commonShadow}`}>
        {/* image (right on md+, top on mobile) */}
        <div className="relative w-28 h-28 md:w-36 md:h-36 flex-shrink-0 rounded-lg">
          {/* image scaler: only this element scales on hover so the ADD pill remains stable */}
          <div className={`w-full h-full rounded-lg overflow-hidden ${commonShadow} transform-gpu` + " " + "group-hover:scale-105"}>
            <ResponsiveImage
              src={product.image}
              alt={product.name}
              className="w-full h-full object-cover object-top"
              sizes="112px"
            />
          </div>

          {/* ADD pill: placed in a sibling layer so image transforms don't nudge it. Centered via flexbox when absolute. */}
          <div className="absolute inset-x-0 bottom-2 flex justify-center pointer-events-none md:bottom-2">
            <motion.button
              aria-label={`Add ${product.name} to cart`}
              className="pointer-events-auto w-full mx-auto text-center bg-white text-emerald-600 font-syncopate font-bold px-6 py-2 rounded-full shadow-sm border border-cream/10 focus:outline-none focus-visible:ring-2 focus-visible:ring-gold/30 md:w-28 md:min-w-[88px] origin-center transform-gpu"
              style={{ transformOrigin: 'center' }}
              whileHover={{ scale: 1.03 }}
              whileTap={{ scale: 0.98 }}
              onClick={(e) => {
                e.stopPropagation();
                onClick(product.id);
              }}
            >
              ADD
            </motion.button>
          </div>

          <div className="hidden md:block md:absolute md:left-1/2 md:-translate-x-1/2 md:bottom-[-1.25rem] w-max text-xs text-cream/60 mt-2">{product.isCustomisable ? 'Customisable' : ''}</div>
        </div>

        {/* content */}
        <div className="flex-1 pr-2 md:pr-6 max-w-[60ch] mx-auto">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-start gap-3 w-full">
              <div className="flex-shrink-0">
                <div className="w-6 h-6 border-2 border-green-500 rounded flex items-center justify-center bg-obsidian/80">
                  <div className="w-3 h-3 rounded-full bg-green-500" />
                </div>
              </div>

              <div className="min-w-0">
                <div className="flex items-baseline gap-3">
                  <h3 className="font-syncopate text-base text-cream leading-tight truncate">
                    {product.name}
                    {product.weight && (
                      <span className="font-outfit text-xs text-cream/60 ml-2">[{product.weight}]</span>
                    )}
                  </h3>
                </div>

                <div className="mt-2 flex items-center gap-4">
                  <span className="font-syncopate text-lg text-gold font-bold">₹{product.price}</span>

                  <div className="flex items-center gap-2">
                    <i className="ri-star-fill text-green-500 text-sm" />
                    <span className="font-outfit text-sm text-green-500">{Number(product.rating).toFixed(1)}</span>
                    <span className="font-outfit text-xs text-cream/50">({product.reviews})</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <p className="font-outfit text-sm text-cream/60 mt-3 line-clamp-2">{product.description}</p>
        </div>
      </div>
    </Animated>
  ) : (
    <motion.div
      key={product.id}
      className="group relative glass-panel rounded-2xl overflow-hidden cursor-pointer border border-gold/10 hover:border-gold/40 transition-all flex-shrink-0 w-72"
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, delay: index * 0.05 }}
      onClick={() => onClick(product.id)}
      whileHover={{ y: -6, boxShadow: '0 15px 30px rgba(197, 160, 33, 0.3)' }}
    >
      <div className="absolute top-3 left-3 z-10 w-5 h-5 border-2 border-green-500 rounded flex items-center justify-center bg-obsidian/80 backdrop-blur-sm">
        <div className="w-2.5 h-2.5 rounded-full bg-green-500"></div>
      </div>

      {product.isBestSeller && (
        <div className="absolute top-3 right-3 z-10 px-2 py-1 bg-gradient-to-r from-gold to-gold-light rounded-full gold-shimmer-effect">
          <span className="font-outfit text-[10px] font-bold text-obsidian whitespace-nowrap">
            ⭐ BEST SELLER
          </span>
        </div>
      )}

      <div className="relative w-full h-48 overflow-hidden">
        <img
          src={product.image}
          alt={product.name}
          className="w-full h-full object-cover object-top group-hover:scale-110 transition-transform duration-500"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-cocoa via-transparent to-transparent opacity-60"></div>
      </div>

      <div className="p-4">
        <h3 className="font-syncopate text-sm text-cream leading-tight mb-2">
          {product.name}
        </h3>

        <div className="flex items-center justify-between mb-3">
          <span className="font-syncopate text-lg text-gold font-bold">
            ₹{product.price}
          </span>
          <div className="flex items-center gap-1">
            <i className="ri-star-fill text-yellow-400 text-xs"></i>
            <span className="font-outfit text-xs text-cream/80">{product.rating}</span>
          </div>
        </div>

        <motion.button
          className="w-full py-2 bg-gradient-to-r from-gold to-gold-light text-obsidian font-syncopate font-bold text-[10px] tracking-wider rounded-full cursor-pointer whitespace-nowrap"
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          onClick={(e) => {
            e.stopPropagation();
            onClick(product.id);
          }}
        >
          ADD TO CART
        </motion.button>
      </div>
    </motion.div>
  );
};

export default memo(ProductCard);
